public class SpinnerBudgetPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            SpinnerBudgetPanel panel = new SpinnerBudgetPanel();
            java.awt.Component spinnerComp = find(panel, "qty");
            java.awt.Component label = find(panel, "cost");
            check("spinner named qty exists", true, spinnerComp instanceof javax.swing.JSpinner);
            check("label named cost exists", true, label instanceof javax.swing.JLabel);
            check("initial cost (qty 1)", "$4.25", textOf(label));
            if (spinnerComp instanceof javax.swing.JSpinner) {
                javax.swing.JSpinner spinner = (javax.swing.JSpinner) spinnerComp;
                spinner.setValue(3);
                check("cost for qty 3", "$12.75", textOf(label));
                spinner.setValue(0);
                check("cost for qty 0", "$0.00", textOf(label));
                spinner.setValue(10);
                check("cost for qty 10", "$42.50", textOf(label));
                spinner.setValue(7);
                check("cost for qty 7", "$29.75", textOf(label));
            } else {
                failures++;
                System.out.println("FAIL  JSpinner not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

