import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;

public class SpinnerBudgetPanel extends JPanel {

    private final JSpinner qty = new JSpinner(new SpinnerNumberModel(1, 0, 10, 1));
    private final JLabel cost = new JLabel("");

    public SpinnerBudgetPanel() {
        qty.setName("qty");
        cost.setName("cost");
        add(qty);
        add(cost);
        qty.addChangeListener(e -> updateCost());
        updateCost();
    }

    private void updateCost() {
        int quantity = ((Number) qty.getValue()).intValue();
        cost.setText(String.format(java.util.Locale.US, "$%.2f", quantity * 4.25));
    }
}
